using System;
using UnityEngine;

namespace Astrea;

public class CellariusOmensHandler : ReferenceSingleton<CellariusOmensHandler>
{
	[NonSerialized]
	[Header("Cellarius Omens")]
	public Func<int, int> TridentOfDepthsWaveOmenAction;

	[NonSerialized]
	public Action<int> AncientHelmOmenAction;

	[NonSerialized]
	public Func<int, GameObject, CorruptionPurifyModifierEnum, int> OnPlayerCorruptedDenticleSuitAction;

	[NonSerialized]
	public Action<int> TamedRemorasOmenAction;

	[NonSerialized]
	public Action OnPlayerPlayVirtueOmenAction;

	[NonSerialized]
	public Func<bool, int> RunicOarOmenAction;

	[NonSerialized]
	public bool NadirRingOmenActive;

	[NonSerialized]
	public Func<int, int> SapphireFishingRodOmenAction;

	[NonSerialized]
	public Action<int, GameObject> WaterSwordOmenAction;

	public void ActivateAncientHelmOmen(int purifyAmount)
	{
		AncientHelmOmenAction?.Invoke(purifyAmount);
	}

	public int OnPlayerCorruptedDenticleSuit(int corruptAmount, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum)
	{
		if (OnPlayerCorruptedDenticleSuitAction != null)
		{
			return OnPlayerCorruptedDenticleSuitAction(corruptAmount, source, corruptionPurifyModifierEnum);
		}
		return corruptAmount;
	}

	public void ActivateTamedRemorasOmen(int effectAmount)
	{
		TamedRemorasOmenAction?.Invoke(effectAmount);
	}
}
